const events = $json.collection || [];
const results = [];
for (const se of events) {
  const name = se.name || '';
  if (!/research\s*(with)?\s*n8n/i.test(name)) continue;
  const memberships = se.event_memberships || [];
  const host = memberships[0] || {};
  results.push({
    json: {
      externalId: se.uri || '',
      organizerName: host.user_name || '',
      organizerEmail: host.user_email || '',
      title: name,
      description: '',
      startsAt: se.start_time || '',
      endsAt: se.end_time || '',
      rawPayload: JSON.stringify(se),
    }
  });
}
return results;
